# NeoGeo-68000 设备定义 - R 脚本
# 生成自: SNK/M68K/NeoGeo-68000
# 版本: 1.0
# 日期: 2026-04-16
# 作者: VML Team
# 描述: SNK Neo Geo AES main processor - Motorola 68000 @ 12MHz + Z80 @ 4MHz (audio coprocessor)
# CPU架构: MC68000
# 位宽: 32位
# 时钟频率: 12000000 Hz

# 寄存器地址定义
D0_ADDR <- 0x00  # Data Register 0
